@Repository
public class $!{ClassName}  {

    @Resource
    private $!{EntityMapper} $!{entityMapper};

    @Resource(name = $!{DataSourceConfigName}.SESSION_FACTORY_NAME)
    private SqlSessionFactory sqlSessionFactory;

    /**
     * 幂等保存$!{Comment}  $!{entityDOs}
     *
     * @param userId                    {@code Long} 用户id
     * @param $!{entityDOs} {@link $!{EntityDO}}
     */
    @Transactional(rollbackFor = Exception.class, transactionManager = $!{DataSourceConfigName}.TRANSACTION_NAME)
    public void saveBatch$!{EntityDOs}(Long userId, final Collection<$!{EntityDO}> $!{entityDOs}) {
        if (CollectionUtils.isEmpty($!{entityDOs})) {
            return;
        }

        Map<String, Long> businessKeyToIdMap = getBusinessKeyToIdMap($!{entityDOs});
        List<$!{EntityDO}> insertList = Lists.newArrayListWithExpectedSize($!{entityDOs}.size());
        List<$!{EntityDO}> updateList = Lists.newArrayListWithExpectedSize($!{entityDOs}.size());
        for ($!{EntityDO} $!{entityDO} : $!{entityDOs}) {
			Long oldId = businessKeyToIdMap.get(getBusinessKey($!{entityDO}));
            if (Objects.isNull(oldId)) {
                insertList.add($!{entityDO});
            } else {
				$!{entityDO}.setId(oldId);
                updateList.add($!{entityDO});
            }
        }
        insertBatch$!{EntityDOs}(userId, insertList);
        updateBatch$!{EntityDOs}ByPrimaryKey(userId, updateList);
    }


    /**
     * 批量新增$!{Comment} {@link $!{EntityMapper}#insertSelective(Object)}
     *
     * @param $!{entityDOs} {@link $!{EntityDO}}
     * @return 影响的行数
     */
    @Transactional(rollbackFor = Exception.class, transactionManager = $!{DataSourceConfigName}.TRANSACTION_NAME)
    public void insertBatch$!{EntityDOs}(Long userId, final List<$!{EntityDO}> $!{entityDOs}) {
        if (CollectionUtils.isEmpty($!{entityDOs})) {
             return;
        }
        final MapperBatchAction<$!{tableInfo.name}Mapper> insertBatchAction = MapperBatchAction
                .create($!{tableInfo.name}Mapper.class, sqlSessionFactory);
        for ($!{EntityDO} $!{entityDO} : $!{entityDOs}) {
		    $!{entityDO}.setCreateBy(userId);
            $!{entityDO}.setUpdateBy(userId);
            insertBatchAction.addAction(mapper -> mapper.insertSelective($!{entityDO}));
        }
        insertBatchAction.doBatchActions();
    }

    /**
     * 批量更新$!{Comment} {@link $!{EntityMapper}#updateByPrimaryKeySelective(Object)}
     *
     * @param userId        {@code Long} 用户id
     * @param $!{entityDOs} {@link $!{EntityDO}}
     * @return 影响的行数
     */
    @Transactional(rollbackFor = Exception.class, transactionManager = $!{DataSourceConfigName}.TRANSACTION_NAME)
    public void updateBatch$!{EntityDOs}ByPrimaryKey(Long userId, final List<$!{EntityDO}> $!{entityDOs}) {
        if (CollectionUtils.isEmpty($!{entityDOs})) {
             return;
        }
        final MapperBatchAction<$!{tableInfo.name}Mapper> updateBatchAction = MapperBatchAction
                .create($!{tableInfo.name}Mapper.class, sqlSessionFactory);
        for ($!{EntityDO} $!{entityDO} : $!{entityDOs}) {
		    $!{entityDO}.setUpdateBy(userId);
            UpdateQuery<$!{EntityDO}> updateQuery = UpdateQuery.createQuery($!{EntityDO}.class)
                    .set($!{entityDO}, ignore -> ignore.ignore($!{EntityDO}::getId, 
					$!{EntityDO}::getCreateTime, 
					$!{EntityDO}::getCreateBy,
					$!{EntityDO}::getUpdateTime))
                    .and($!{EntityDO}::getId, isEqual($!{entityDO}.getId()));
            updateBatchAction.addAction(mapper -> mapper.updateByUpdateQuery(updateQuery));
        }
        updateBatchAction.doBatchActions();
    }
    /**
     * 更新$!{Comment} 删除状态
     *
	 * @param userId  用户id
     * @param ids id 列表
     * @param deleted 删除状态枚举
     */
    public void updateDeletedByIds(Long userId, Collection<Long> ids, Deleted deleted) {
        if (CollectionUtils.isEmpty(ids)) {
            return;
        }
        UpdateQuery<$!{EntityDO}> updateQuery = UpdateQuery.createQuery($!{EntityDO}.class)
                .set($!{EntityDO}::getDeleted, deleted.getValue())
                .set($!{EntityDO}::getUpdateBy, userId)
                .and($!{EntityDO}::getId, c -> c.in(ids));
        $!{entityMapper}.updateByUpdateQuery(updateQuery);
    }

    /**
     * 根据id查询$!{Comment} {@link $!{EntityMapper}#selectByPrimaryKey(Object)}
     *
     * @param id id 主键id
     * @return {@link $!{EntityDO}}
     */
    public Optional<$!{EntityDO}> get$!{EntityDO}ById(Long id) {
        return Optional.ofNullable($!{entityMapper}.selectByPrimaryKey(id));
    }

     /**
     * 分页查询 $!{Comment}
     *
     * @param $!{entityQueryBO} {@link $!{EntityQueryBO}}
     * @param pageSize                 每页大小
     * @param pageNum                  页码
     * @return {@link NormPagingResult}
     */
    public NormPagingResult<$!{EntityDO}> pageQuery(
            $!{EntityQueryBO}  $!{entityQueryBO}, Integer pageSize, Integer pageNum, String sortProperty,
            SortDirection sortDirection) {
        NormPagingQuery<$!{EntityDO}> query =
                NormPagingQuery.createQuery($!{EntityDO}.class, pageNum, pageSize, false, true)
                        .and(Objects.nonNull($!{entityQueryBO}.getDeleted()),
                                $!{EntityDO}::getDeleted, isEqual($!{entityQueryBO}.getDeleted()));
        query.addSorts(new SortDescriptor(sortProperty, sortDirection));
        return $!{entityMapper}.selectByNormalPaging(query);
    }

    /**
     * 获取DB中已经存在的  $!{Comment} 数据
     *
     * @return map  key:业务key value:edb指标数据预测id
     */
    public Map<String, Long> getBusinessKeyToIdMap(Collection<$!{EntityDO}> $!{entityDOs}) {
        DynamicQuery<$!{EntityDO}> dynamicQuery = DynamicQuery.createQuery($!{EntityDO}.class)
                .select($!{EntityDO}::getId, $!{EntityDO}::getBusinessKeyField);
        for ($!{EntityDO} $!{entityDO} : $!{entityDOs}) {
            dynamicQuery.or($!{EntityDO}::getId, isEqual($!{entityDO}.getId()));
        }
        return $!{entityMapper}.selectByDynamicQuery(dynamicQuery).stream()
                .collect(Collectors.toMap(this::getBusinessKey, $!{EntityDO}::getId, (v1, v2) -> v2));
    }

    /**
     * 获取$!{Comment}业务key
     *
     * @param $!{entityDO} {@link $!{EntityDO}}
     * @return $!{Comment}业务key
     */
    public String getBusinessKey($!{EntityDO} $!{entityDO}) {
        return String.format("%s:%s", $!{entityDO}.getBusinessKeyField());
    }
}

