    @Resource
    private $!{EntityDAO} $!{entityDAO};
    @Resource
    private OnshoreManagementHttpService onshoreManagementHttpService;

    @Override
    public void insert$!{Entity}(Long userId, $!{EntityDetailDTO} $!{entityDetailDTO}) {
        $!{EntityDO}  $!{entityDO} =
                BeanCopyUtils.copyProperties($!{entityDetailDTO}, $!{EntityDO}.class);
        check$!{Entity}Exist($!{entityDO});
        $!{entityDO}.setCreateBy(userId);
        $!{entityDO}.setUpdateBy(userId);
        $!{entityDO}.setDeleted(Deleted.NO_DELETED.getValue());
        $!{entityDAO}.insertBatch$!{EntityDOs}(userId, Lists.newArrayList($!{entityDO}));
    }

    @Override
    public void updateDeletedByIds(Long userId, Collection<Long> ids, Deleted deleted) {
        $!{entityDAO}.updateDeletedByIds(userId, ids, deleted);
    }

    @Override
    public void update$!{Entity}(Long userId, $!{EntityDetailDTO} $!{entityDetailDTO}) {
        $!{EntityDO} $!{entityDO} =
                BeanCopyUtils.copyProperties($!{entityDetailDTO}, $!{EntityDO}.class);
        check$!{Entity}Exist($!{entityDO});
        $!{entityDO}.setUpdateBy(userId);
        $!{entityDAO}.updateBatch$!{EntityDOs}ByPrimaryKey(userId, Lists.newArrayList($!{entityDO}));
    }

    private void check$!{Entity}Exist($!{EntityDO} $!{entityDO}) {
        Map<String, Long> businessKeyToIdMap = $!{entityDAO}.getBusinessKeyToIdMap(Lists.newArrayList($!{entityDO}));
        String businessKey = $!{entityDAO}.getBusinessKey($!{entityDO});
        Long existId = businessKeyToIdMap.get(businessKey);
        if (!(Objects.isNull(businessKeyToIdMap.get(businessKey)) || Objects.equals(existId, $!{entityDO}.getId()))) {
            throw new BusinessException("业务主键数据重复,请检查数据!");
        }
    }

    @Override
    public $!{EntityDetailDTO} get$!{Entity}ById(Long id) {
        return $!{entityDAO}.get$!{EntityDO}ById(id)
                .map($!{entityDO} -> BeanCopyUtils.copyProperties($!{entityDO}, $!{EntityDetailDTO}.class))
                .orElseGet(() -> {
                    logger.warn("db data not found by id: {}", id);
                    return null;
                });
    }

    @Override
    public NormPagingResult<$!{EntityPageDTO}> pageQuery($!{EntityQueryDTO} $!{entityQueryDTO}, Integer pageSize,
                                                              Integer pageNum, String sortProperty, SortDirection sortDirection) {
        $!{EntityQueryBO} $!{entityQueryBO} =
                BeanCopyUtils.copyProperties(edbIndicatorPredictionQueryDTO, $!{EntityQueryBO}.class);
        NormPagingResult<$!{EntityDO}> pagingResult =
                $!{entityDAO}.pageQuery($!{entityQueryBO}, pageSize, pageNum, sortProperty, sortDirection);

        Long[] userIds = pagingResult.getList().stream().map($!{EntityDO}::getUpdateBy).toArray(Long[]::new);
        Map<Long, String> userIdMap = onshoreManagementHttpService.getUserIdMap(userIds);
        List<$!{EntityPageDTO}> pageDTOList = pagingResult.getList().stream()
                .map($!{entityDO} -> {
                    $!{EntityPageDTO} $!{entityPageDTO} =
                            BeanCopyUtils.copyProperties($!{entityDO}, $!{EntityPageDTO}.class);
                    $!{entityPageDTO}.setUpdateByDis(userIdMap.get($!{entityDO}.getUpdateBy()));
                    return $!{entityPageDTO};
                })
                .collect(Collectors.toList());
        NormPagingResult<$!{EntityPageDTO}> normPagingResult = new NormPagingResult<>();
        BeanCopyUtils.copyProperties(pagingResult, normPagingResult);
        normPagingResult.setList(pageDTOList);
        return normPagingResult;
    }
}

